// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    ReentrantAttacker attacker;

    function setUp() public { c = new ReentrancyDAO(); attacker = new ReentrantAttacker(c); }

    function testFuzz_property(uint256 depositAmount, bool doReentrancy) public {
        depositAmount = bound(depositAmount, 0, 1 ether);
        vm.deal(address(attacker), depositAmount);

        if (depositAmount == 0) {
            vm.prank(address(attacker));
            c.deposit{value: 0}();

            vm.prank(address(attacker));
            c.withdrawAll();

            assertTrue(address(c).balance == 0);
            return;
        }

        attacker.setReenter(doReentrancy);

        vm.prank(address(attacker));
        c.deposit{value: depositAmount}();

        vm.prank(address(attacker));
        attacker.callWithdrawAll();

        assertTrue(address(c).balance == 0);
    }
}

contract ReentrantAttacker {
    ReentrancyDAO public c;
    bool public reenter;
    bool internal inCall;

    constructor(ReentrancyDAO _c) {
        c = _c;
    }

    function setReenter(bool r) external {
        reenter = r;
    }

    function callWithdrawAll() external {
        c.withdrawAll();
    }

    receive() external payable {
        if (reenter && !inCall) {
            inCall = true;
            c.withdrawAll();
            inCall = false;
        }
    }
}
